		-- 02 CUOTAS PAGADAS		
			
				-- agregando columnas
				ALTER TABLE #tab03
				Add CuotaPag decimal(10,5), CuotaPend decimal(10,5)
				--Drop column CuotaPag , CuotaPend , Porcentaje ,DiasPromAtr 

	------------------------CURSOR-----------------------------------
		Declare @ccodcred varchar(18), @CuotaPag decimal(10,5), @CuotaPend decimal(10,5), 
		    @CuotasAprob decimal(10,5) 			
						
			Declare cAmpl CURSOR FOR	
				Select distinct CodigoCredito from #tab02 (NOLOCK) 	

			OPEN cAmpl
				FETCH cAmpl into @ccodcred
				WHILE (@@FETCH_STATUS=0)
				BEGIN	
				
				set @CuotasAprob = (select NumeroCuotas from #tab03 where CodigoCredito = @ccodcred)
				set @CuotaPag = 
						(select count(distinct cNumCuoPla) 
						 from [HYO00402].SOFCMACHYO_DIARIO_MANIANA.dbo.[KPYDPLANPAGCRE] B (NOLOCK)
							where cCodCtaCre = @ccodcred and cCodEstCuo = 'P'
								AND cCodPlaPag in 
									(select max(cCodPlaPag) 
									 from [HYO00402].SOFCMACHYO_DIARIO_MANIANA.dbo.[KPYDPLANPAGCRE] B (NOLOCK)
										WHERE cCodEstCuo = 'P'
											and cCodCtaCre = @ccodcred))			
														
						set @CuotaPend = (@CuotasAprob - @CuotaPag )																										
																										
						UPDATE #tab03
						SET CuotaPag = @CuotaPag
						WHERE CodigoCredito = @ccodcred	

						UPDATE #tab03
						SET CuotaPend = @CuotaPend
						WHERE CodigoCredito = @ccodcred											
				
				FETCH cAmpl INTO @ccodcred
				END
				CLOSE cAmpl
				DEALLOCATE cAmpl

