		--03 AGREGANDO GARANTIAS
		
			-- Drop table #tab077
			Select * into #tab077 from (
				Select A.CodigoCredito, GARLIN.cCodLinCre, CodigoGarantia = GARLIN.CCODGARCLI 
				,CodCliente = GARLIN.CCODCLIENTE 
				,TipoGarantia = GARLIN.CCODTIPGAR
				--,GARLIN.CCODTIPMON 
				,DescripcionTipoGarantia = TIPGAR.CDESTIPGAR
				, Moneda = GARLIN.CCODTIPMON -- M.CDESCORTA
				,MontoGravamen=  sum(isnull(GARLIN.nMonGraGarSol,0)) -- sum(GARLIN.nMonTasGar)
				--,MontoGravamen=  sum(GARLIN.nMonGraGarSol) -- sum(GARLIN.nMonTasGar)
				,MontoGravamenSoles =  
					Case GARLIN.CCODTIPMON
					when '1'  then  sum(isnull(GARLIN.nMonGraGarSol,0)) 		
					when '2' then  sum(isnull(GARLIN.nMonGraGarSol,0)) * GARLIN.nTipCamGar		
					end													
				,DeparGarantia = isnull(DE.cCodDepart,'0')				
				,ProvGarantia = isnull(PR.cCodProvin,'0')				
				,DisttGarantia = isnull(DI.cCodDistri,'0') 		
				From #tab03 A				
					inner join KPYDGARLINCRE GARLIN (NOLOCK) 
						on GARLIN.cCodLinCre = A.cCodLinCre
					inner JOIN GENDGARANTIA TIPGAR (NOLOCK)
						ON TIPGAR.CCODgarant = GARLIN.CCODTIPGAR and TIPGAR.lconestado = 1
				
					INNER join [HYO00402].CMACHYOCLI_MANIANA.dbo.CLIMGarCliente CG				
						on CG.cCodCliente = GARLIN.cCodCliente 
							and CG.cCodTipGar = GARLIN.cCodTipGar
							and CG.cCodGarCli = GARLIN.cCodGarCli
					INNER join [HYO00402].CMACHYOCLI_MANIANA.dbo.CLIDDirGarant CD
						on CD.cCodCliente = GARLIN.cCodCliente 
							and CD.cCodGarCli = GARLIN.cCodGarCli 					
					inner join GENTDepartame DE
						on DE.cCodDepart = CD.cCodDepart
					inner join GENTProvincia PR
						on PR.cCodProvin = CD.cCodProvin and PR.cCodDepart = CD.cCodDepart
					inner join GENTDistrito DI 
						on DI.cCodDistri = CD.cCodDistri and DI.cCodDepart = CD.cCodDepart
							and DI.cCodProvin = CD.cCodProvin
				
				Where GARLIN.cCodEstGar = 'A'				
				Group By A.CodigoCredito, GARLIN.cCodLinCre , GARLIN.CCODGARCLI
				,GARLIN.CCODCLIENTE , GARLIN.CCODTIPGAR, GARLIN.CCODTIPMON
				,GARLIN.nTipCamGar, DE.cCodDepart, PR.cCodProvin, DI.cCodDistri 
				--, GARLIN.CCODTIPMON  
				,TIPGAR.CDESTIPGAR --,M.CDESCORTA
				--Order by FIA.CCODCTACRE
				) as tmp	
	
			-- drop table #tab078
					Select * into #tab078 from 
							(select top 1 cCodLinCre,DescripcionTipoGarantia
								,MontoGravamenSoles,DeparGarantia,ProvGarantia
								,DisttGarantia 
							from #tab077 ) as tmp
					-- Select * from #tab078
					Delete from #tab078

					  --UNA SOLA GARANTIA
					  Insert Into #tab078
							Select cCodLinCre,DescripcionTipoGarantia
								,MontoGravamenSoles,DeparGarantia,ProvGarantia
								,DisttGarantia 
							from #tab077 
							where cCodLinCre in (
									Select cCodLinCre --, count(CodigoGarantia) 
									from #tab077 
									Group By cCodLinCre
									Having count(CodigoGarantia) = 1
					  					  )
					 -- MAS DE 2 GARANTIAS
					 -- drop table #tab033
					 -- drop table #tab079
					 Select * into #tab079 from 
						( select top 1 
							cCodLinCre,DescripcionTipoGarantia
							,MontoGravamenSoles,DeparGarantia,ProvGarantia
								,DisttGarantia 
							from #tab077 ) as tmp
					 -- Select * from #tab079
