	----------------------------cursor -----------------------
					Declare @codLinCre char(18) 
				
					Declare cG01 CURSOR FOR
						select distinct cCodLinCre from #tab079 (NOLOCK)
					OPEN cG01
					FETCH cG01 into @codLinCre
					WHILE (@@FETCH_STATUS=0)
					BEGIN				
						Insert into #tab078
							Select top 1					
							cCodLinCre,DescripcionTipoGarantia='GarantiasMixtas'
							,MontoGravamenSoles=sum(MontoGravamenSoles)
							,DeparGarantia,ProvGarantia
							,DisttGarantia 
							from #tab079
							Where cCodLinCre = @codLinCre
							Group By cCodLinCre,DeparGarantia,ProvGarantia,DisttGarantia 							

					FETCH cG01 INTO @codLinCre
