						--   1742.46

		Select cNumCuoPla,nMonGasGen  -- * 
		From HIPDGasGenCuo 
		Where cCodCtaCre = '107002101009426521' -- and cCodEstGas = 'E'
			and cNumCuoPla = 
				(select min(cNumCuoPla) 
					From HIPDGasGenCuo (NOLOCK)
