	Alter Table #tab04
	Add Cuota decimal(10,5)
	/*
		Add CuotaPag decimal(10,5), CuotaPend decimal(10,5)
		Select *  from #tab04
	*/
	----------------------------cursor -----------------------
					Declare @credito1 char(18),  @MonGas decimal (10,5), @Monto decimal(10,5), @Cuota decimal (10,5)
				
					Declare cC01 CURSOR FOR
						Select CodigoCredito from #tab04 (NOLOCK)						
					OPEN cC01
					FETCH cC01 into @credito1
					WHILE (@@FETCH_STATUS=0)
					BEGIN				
						
					Set @Monto =
						(Select Cuota = B.nMonCapPro + B.nMonIntPro
						 from [HYO00402].SOFCMACHYO_DIARIO_MANIANA.dbo.[KPYDPLANPAGCRE] B (NOLOCK)
							where cCodCtaCre = @credito1 
								AND cCodPlaPag in 
									(select max(cCodPlaPag) 
									 from [HYO00402].SOFCMACHYO_DIARIO_MANIANA.dbo.[KPYDPLANPAGCRE] B (NOLOCK)
										WHERE cCodCtaCre = @credito1 )
								and cNumCuoPla = 
									(select min(cNumCuoPla) 
									 from [HYO00402].SOFCMACHYO_DIARIO_MANIANA.dbo.[KPYDPLANPAGCRE] B (NOLOCK)
										WHERE cCodCtaCre = @credito1))
							
					Set @MonGas = 
						(Select nMonGasGen
							From HIPDGasGenCuo 
							Where cCodCtaCre = @credito1 and cCodEstGas = 'E'
								and cNumCuoPla = 
									(select min(cNumCuoPla) 
										From HIPDGasGenCuo (NOLOCK)
										WHERE cCodCtaCre = @credito1 ))

					Set @Cuota = isnull(@Monto,0) + isnull(@MonGas,0)

						Update #tab04
						Set Cuota = @Cuota
						Where CodigoCredito = @credito1   							

					FETCH cC01 INTO @credito1
					END
					CLOSE cC01
					DEALLOCATE cC01

	-------------------------------------------------------------------		

		 /*		
			Select *  from #tab04
		*/



	----------------------------------------------------------------------------------------	
		-- FINAL
		
		Select A.* 
			, TipoFuenteIngresos = 
				CASE DFI.cCodTipFin
				WHEN 'I' THEN 'INDEPENDIENTE'
				WHEN 'D' THEN 'DEPENDIENTE'
				ELSE 'NO REGISTRA' END
			, NombreFuenteIngresos = ISNULL(DFI.cNomEmp,'NO REGISTRA')
		From #tab04 A
			left join #fi DFI				
				ON DFI.cCodCliente COLLATE SQL_Latin1_General_CP1_CI_AS = A.CodigoCliente
		